package org.mockito.internal.creation.bytebuddy;

import java.io.*;
import java.lang.reflect.Constructor;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.exceptions.base.MockitoException;
import org.mockito.exceptions.bytecode.MockitoException;
import org.mockito.internal.InternalMockHandler;
import org.mockito.internal.configuration.GlobalConfiguration;
import org.mockito.internal.creation.MockHandler;
import org.mockito.internal.creation.instance.*;
import org.mockito.internal.creation.instantiation.ClassInstantiator;
import org.mockito.internal.creation.internal.MockMethodInterceptor;
import org.mockito.internal.utilities.settings.MockCreationSettings;
import org.mockito.internal.utilities.settings.SerializableMode;
import org.mockito.invocation.MockHandler;
import org.mockito.mock.MockCreationSettings;
import org.mockito.mock.SerializableMode;
import org.mockito.plugins.MockMaker;
import org.powermock.api.mockito.PowerMockito;
import org.powermock.core.classloader.annotations.PrepareForTest;
import org.powermock.modules.junit4.PowerMockRunner;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

@PrepareForTest({ByteBuddyMockMaker.class})
public class ByteBuddyMockMaker_createMock_TriageGen2Test {

    private ByteBuddyMockMaker mockMaker;
    private MockCreationSettings<Object> settings;
    private MockHandler handler;
    private BytecodeGenerator cachingMockBytecodeGenerator;
    private ClassInstantiator classInstantiator;

    // Mocking the interface for the internal cache
    public interface BytecodeGenerator {
        <T> Class<? extends T> get(Class<T> type, Class<?>... extraInterfaces);
    }

    // Mocking the interceptor access interface
    public interface MockAccess {
        void setMockitoInterceptor(MockMethodInterceptor interceptor);
    }

    @Before
    public void setUp() throws Exception {
        mockMaker = PowerMockito.spy(new ByteBuddyMockMaker());
        settings = mock(MockCreationSettings.class);
        handler = mock(MockHandler.class);

        // We need to inject these internal fields via reflection because they are private
        cachingMockBytecodeGenerator = mock(BytecodeGenerator.class);
        classInstantiator = mock(ClassInstantiator.class);

        setInternalField(mockMaker, "cachingMockBytecodeGenerator", cachingMockBytecodeGenerator);
        setInternalField(mockMaker, "classInstantiator", classInstantiator);
    }

    private void setInternalField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test(expected = MockitoException.class)
    public void createMock_ThrowsException_WhenSerializableModeIsAcrossClassLoaders() {
        when(settings.getSerializableMode()).thenReturn(SerializableMode.ACROSS_CLASSLOADERS);
        mockMaker.createMock(settings, handler);
    }

    @Test
    public void createMock_Success_WhenAllConditionsMet() throws Exception {
        Class<Object> typeToMock = Object.class;
        Class<Object> proxyType = (Class<Object>) PowerMockito.mock(Object.class);
        Object mockInstance = mock(MockAccess.class);

        when(settings.getSerializableMode()).thenReturn(SerializableMode.DEFAULT);
        when(settings.getTypeToMock()).thenReturn(typeToMock);
        when(cachingMockBytecodeGenerator.get(eq(typeToMock), any())).thenReturn(proxyType);
        when(classInstantiator.instantiate(proxyType)).thenReturn(mockInstance);

        // Mocking ensureMockIsAssignableToMockedType logic by spying/stubbing if possible 
        // or ensuring the instance is indeed an instance of the type.
        // Since we can't easily mock the private method ensureMockIsAssignableToMockedType, 
        // we rely on the fact that it's a private method in the same class.
        // In a real scenario, we'd use PowerMock to stub the private method.
        PowerMockito.doReturn(mockInstance).when(mockMaker, "ensureMockIsAssignableToMockedType", eq(settings), eq(mockInstance));

        Object result = mockMaker.createMock(settings, handler);

        assert result == mockInstance;
    }

    @Test(expected = MockitoException.class)
    public void createMock_ThrowsException_WhenClassCastExceptionOccurs() throws Exception {
        Class<Object> typeToMock = Object.class;
        Class<Object> proxyType = (Class<Object>) Object.class;
        Object wrongInstance = new Object(); // Not implementing MockAccess

        when(settings.getSerializableMode()).thenReturn(SerializableMode.DEFAULT);
        when(settings.getTypeToMock()).thenReturn(typeToMock);
        when(cachingMockBytecodeGenerator.get(eq(typeToMock), any())).thenReturn(proxyType);
        when(classInstantiator.instantiate(proxyType)).thenReturn(wrongInstance);

        mockMaker.createMock(settings, handler);
    }

    @Test(expected = MockitoException.class)
    public void createMock_ThrowsException_WhenInstantiationExceptionOccurs() throws Exception {
        Class<Object> typeToMock = Object.class;
        Class<Object> proxyType = (Class<Object>) Object.class;

        when(settings.getSerializableMode()).thenReturn(SerializableMode.DEFAULT);
        when(settings.getTypeToMock()).thenReturn(typeToMock);
        when(cachingMockBytecodeGenerator.get(eq(typeToMock), any())).thenReturn(proxyType);
        when(classInstantiator.instantiate(proxyType)).thenThrow(new org.mockito.internal.creation.instance.InstantiationException("Fail"));

        mockMaker.createMock(settings, handler);
    }
}
